CREATE TABLE `entrepreneur` (`Entrepreneur_ID` DECIMAL(18,2), `People_ID` DECIMAL(18,2), `Company` VARCHAR(100), `Money_Requested` DECIMAL(18,2), `Investor` VARCHAR(100));
CREATE TABLE `people` (`People_ID` DECIMAL(18,2), `Name` VARCHAR(100), `Height` DECIMAL(18,2), `Weight` DECIMAL(18,2), `Date_of_Birth` VARCHAR(100));
